svg.script:
// Clouds: same switch as the sea (#animate). Each cloud shape (#cloud-N in <defs>) is shown twice,
// once in #clouds and once, offset, in #cloud-shadows, so a shadow always matches its cloud.
(function () {
  if (!/(^|[#&])animate\b/.test(location.hash)) return;
  var NS = 'http://www.w3.org/2000/svg';
  // Same rotated frame as the wave crests: drift is along local -x (west and slightly south).
  var ANG = 12, CX = 1900, CY = 760;
  var C = Math.cos(ANG * Math.PI / 180), S = Math.sin(ANG * Math.PI / 180);
  var M = 90;   // margin beyond the map edge: feathering, roughness and the shadow offset
  function toLocal(x, y) {
    return [CX + (x - CX) * C - (y - CY) * S, CY + (x - CX) * S + (y - CY) * C];
  }
  var MAP = [toLocal(0, 0), toLocal(2000, 0), toLocal(2000, 1520), toLocal(0, 1520)];
  var BIG = [toLocal(-M, -M), toLocal(2000 + M, -M), toLocal(2000 + M, 1520 + M), toLocal(-M, 1520 + M)];
  var Y0 = Math.min.apply(null, MAP.map(function (p) { return p[1]; })),
      Y1 = Math.max.apply(null, MAP.map(function (p) { return p[1]; }));

  // Leftmost / rightmost x of the (enlarged) map within the band y0..y1, in the local frame
  function span(y0, y1) {
    var lo = Infinity, hi = -Infinity;
    function take(x) { if (x < lo) lo = x; if (x > hi) hi = x; }
    for (var i = 0; i < 4; i++) {
      var a = BIG[i], b = BIG[(i + 1) % 4];
      if (a[1] >= y0 && a[1] <= y1) take(a[0]);
      [y0, y1].forEach(function (yy) {
        if ((a[1] - yy) * (b[1] - yy) < 0) take(a[0] + (b[0] - a[0]) * (yy - a[1]) / (b[1] - a[1]));
      });
    }
    return [lo, hi];
  }

  // Lumpy cloud: flat-ish base plus a heap of overlapping puffs and a few ragged fringe puffs
  function reshape(g, w, h) {
    while (g.firstChild) g.removeChild(g.firstChild);
    var parts = [[0, h * 0.08, w * 0.44, h * 0.26]], n = 9 + Math.floor(Math.random() * 6), i;
    for (i = 0; i < n; i++) {
      var t = Math.random() * 2 - 1, dome = Math.sqrt(Math.max(0, 1 - t * t)),
          r = h * (0.20 + 0.22 * Math.random()) * (0.55 + 0.45 * dome);
      parts.push([t * w * 0.40, -h * 0.30 * dome * Math.random() + h * 0.06, r, r]);
    }
    var m = 3 + Math.floor(Math.random() * 3);
    for (i = 0; i < m; i++) {
      var a = Math.random() * Math.PI * 2;
      parts.push([Math.cos(a) * w * 0.47, Math.sin(a) * h * 0.30,
                  h * (0.08 + 0.08 * Math.random()), h * (0.07 + 0.06 * Math.random())]);
    }
    parts.forEach(function (p) {
      var e = document.createElementNS(NS, 'ellipse');
      e.setAttribute('cx', p[0].toFixed(1)); e.setAttribute('cy', p[1].toFixed(1));
      e.setAttribute('rx', p[2].toFixed(1)); e.setAttribute('ry', p[3].toFixed(1));
      g.appendChild(e);
    });
  }

  // New shape, size and track; start beyond the east edge, finish beyond the west/south edge
  function place(i, band) {
    var w = 150 + Math.random() * 170, h = w * (0.42 + Math.random() * 0.18);
    reshape(document.getElementById('cloud-' + i), w, h);
    var y = band == null ? Y0 + Math.random() * (Y1 - Y0)
                         : Y0 + (band + 0.15 + Math.random() * 0.7) / NBANDS * (Y1 - Y0);
    var sp = span(y - h * 0.75, y + h * 0.45), hw = w * 0.55;
    var x0 = sp[1] + hw, x1 = sp[0] - hw;
    var uses = document.querySelectorAll('#weather use[data-i="' + i + '"]');
    for (var k = 0; k < uses.length; k++) {
      uses[k].setAttribute('x', x0.toFixed(1));
      uses[k].setAttribute('y', y.toFixed(1));
      uses[k].style.setProperty('--dx', (x1 - x0).toFixed(1) + 'px');
    }
  }

  var clouds = document.querySelectorAll('#clouds .cloud'), n = clouds.length, bands = [], j;
  var NBANDS = n;
  for (j = 0; j < n; j++) bands.push(j);
  for (j = n - 1; j > 0; j--) { var r = Math.floor(Math.random() * (j + 1)), t = bands[j]; bands[j] = bands[r]; bands[r] = t; }
  // Spread out across the map to begin with, then random
  for (j = 0; j < n; j++) place(clouds[j].getAttribute('data-i'), bands[j]);
  document.getElementById('clouds').addEventListener('animationiteration', function (e) {
    if (e.target.classList.contains('cloud')) place(e.target.getAttribute('data-i'));
  });
})();
